const pages={home:'Overview',assistant:'Ask CyberShield',device:'Device check',threats:'Threat briefings',learn:'Learn',privacy:'Privacy center'};
const concepts=[
 {title:'Cybersecurity',icon:'🛡️',simple:'Cybersecurity is how we protect our devices, accounts, and personal information from harm.',example:'Like locking your front door, using a screen lock helps keep strangers out of your phone.',happens:'People use protective settings and habits. Criminals may try to trick people or exploit weak settings.',signs:'Unexpected account alerts, unfamiliar sign-ins, or requests for codes can deserve a closer look.',protect:'Use unique passwords, turn on multi-factor authentication, update devices, and pause before tapping unexpected links.',affected:'Secure the affected account from its official app or website, change reused passwords, and contact the service if needed.',technical:'A broad discipline covering confidentiality, integrity, availability, identity, and systems security.'},
 {title:'Phishing',icon:'🎣',simple:'Phishing is a fake message designed to trick you into sharing information or opening something unsafe.',example:'A text pretending to be your bank says “Your account is blocked—sign in here now.”',happens:'A scammer imitates a trusted person or company and creates pressure to act quickly.',signs:'Unexpected urgency, strange sender details, links that do not match the real site, or requests for a password or code.',protect:'Do not use the message link. Open the service’s official app yourself or call a trusted number.',affected:'If you entered a password, change it from the official app and secure any account that reused it. Contact your bank if money or bank details are involved.',technical:'A social-engineering attack that uses impersonation to induce credential disclosure, malicious execution, or other unsafe actions.'},
 {title:'Password',icon:'🔑',simple:'A password is a secret phrase that helps prove an account belongs to you.',example:'A unique long passphrase is like giving each house a different key.',happens:'Attackers may guess common passwords, reuse credentials leaked elsewhere, or trick people into sharing them.',signs:'Sign-in alerts you do not recognize, password reset emails you did not request, or unexpected lockouts.',protect:'Use a password manager, make every password unique, and turn on a second sign-in step.',affected:'Change the password through the official site, sign out other sessions if offered, and update any reused password.',technical:'A knowledge factor used in authentication; risk is affected by entropy, reuse, phishing resistance, and verifier controls.'},
 {title:'Malware',icon:'🦠',simple:'Malware is software made to harm a device, spy, or take information without permission.',example:'A fake app may pretend to be a game but secretly show unwanted ads or collect data.',happens:'It may arrive through an untrusted app, attachment, download, or security weakness.',signs:'Unfamiliar apps, unusual pop-ups, unexpected settings changes, or behavior that started after a new download. These signs can have harmless causes too.',protect:'Install apps from official stores, review permissions, keep software updated, and remove apps you do not trust.',affected:'Disconnect from sensitive accounts, avoid entering passwords on the device, uninstall the suspicious app if safe, and seek trusted support.',technical:'A broad class including trojans, worms, spyware, ransomware, and other unwanted code.'},
 {title:'Ransomware',icon:'🔒',simple:'Ransomware is malware that locks or encrypts files and demands payment.',example:'A business may suddenly be unable to open its work documents.',happens:'It can enter through a fake attachment, stolen login, or vulnerable system.',signs:'Files stop opening, names change, or a ransom note appears.',protect:'Keep a separate backup, update software, use MFA, and be careful with unexpected attachments.',affected:'Do not rush to pay. Disconnect affected devices from networks if safe, preserve evidence, and contact your IT/security support or local authorities.',technical:'Malicious encryption or system disruption paired with extortion; incident response should preserve evidence and contain spread.'},
 {title:'Data breach',icon:'📂',simple:'A data breach is when private information is accessed or exposed by someone who should not have it.',example:'A service tells customers that email addresses and passwords may have been exposed.',happens:'A company account, database, or device may be accessed without authorization.',signs:'A credible notice from a service, unfamiliar logins, or password reset alerts.',protect:'Use different passwords for every service, enable MFA, and keep recovery details current.',affected:'Use the service’s official site to understand what was exposed. Change affected and reused passwords, and watch for follow-up scams.',technical:'Unauthorized access, disclosure, alteration, or loss of protected data; scope and confirmed facts depend on the investigation.'},
 {title:'Public Wi-Fi',icon:'📶',simple:'Public Wi-Fi is a shared internet connection in places like cafés and airports.',example:'Anyone nearby may be connected to the same hotspot, including a scammer who made a fake network name.',happens:'An open network may not be operated by who it claims, or may expose unencrypted traffic.',signs:'A network name you did not expect, a login page asking for unusual details, or a certificate warning.',protect:'Use trusted networks or mobile data for sensitive tasks, keep HTTPS warnings in view, and use a reputable VPN if you already have one.',affected:'If you signed into a suspicious page, change that password on a trusted connection and review account sessions.',technical:'Risks include rogue access points, traffic interception, DNS manipulation, and local network attacks.'},
 {title:'Two-step sign-in',icon:'🔐',simple:'Two-step sign-in asks for a second proof after your password, such as a prompt or security key.',example:'A thief who learns your password still may not be able to sign in without your device or key.',happens:'The account checks more than one factor before allowing access.',signs:'Unexpected approval requests mean someone may be trying to sign in; deny requests you did not start.',protect:'Turn it on in important accounts. Prefer passkeys or security keys when available; never share one-time codes.',affected:'Deny unexpected prompts, change your password, and review active sessions from the official account settings.',technical:'Multi-factor authentication combines independent factors; phishing-resistant FIDO credentials reduce relay risk.'}
];
const modal=document.getElementById('modal'),toast=document.getElementById('toast');let toastTimer;let lessonModalIndex=null;let activeModalAction=null;let activeUserId=null;let learningState={completed:[],level:'Beginner',quizResults:{}};
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
function navigate(page){if(!pages[page])return;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumb').textContent=pages[page];history.replaceState(null,'',`#${page}`);window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));
function openModal(title,html,kicker='QUICK GUIDE'){lessonModalIndex=null;activeModalAction=null;document.getElementById('modal-done').textContent='Got it →';document.getElementById('modal-title').textContent=title;document.getElementById('modal-kicker').textContent=kicker;document.getElementById('modal-body').innerHTML=html;modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.getElementById('modal-close').focus()}
function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');lessonModalIndex=null;activeModalAction=null}
document.getElementById('modal-close').onclick=closeModal;document.getElementById('modal-done').onclick=()=>{if(activeModalAction){const action=activeModalAction;activeModalAction=null;action()}else if(lessonModalIndex===null)closeModal();else completeLesson(lessonModalIndex)};modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function conceptHtml(c){return `<p><strong>In simple terms</strong><br>${c.simple}</p><p><strong>A real-world example</strong><br>${c.example}</p><p><strong>How it happens</strong><br>${c.happens}</p><p><strong>Warning signs</strong><br>${c.signs}</p><p><strong>How to protect yourself</strong><br>${c.protect}</p><p><strong>If you may be affected</strong><br>${c.affected}</p><p><strong>Technical explanation</strong><br>${c.technical}</p>`}
const lessonModules=[
 {title:'Cybersecurity Basics',minutes:4,icon:'🛡️',summary:'Learn the everyday habits that help protect your devices, accounts, and personal information.',lesson:concepts[0]},
 {title:'Online Safety',minutes:5,icon:'🧭',summary:'Recognize common online tricks and choose a safer next step before you click or reply.',lesson:concepts[1]},
 {title:'Mobile Security',minutes:5,icon:'📱',summary:'Understand app permissions, software updates, and warning signs on a phone.',lesson:concepts[3]},
 {title:'Network Security',minutes:5,icon:'📶',summary:'Learn what shared Wi-Fi can and cannot protect, and how to handle login pages.',lesson:concepts[6]},
 {title:'Web Security',minutes:6,icon:'🌐',summary:'Check links and websites carefully, and use official apps for sensitive actions.',lesson:{title:'Web security',simple:'Web security is the set of practices that helps protect websites and the people who use them.',example:'A fake bank page may look real but use a slightly different web address.',happens:'Attackers imitate trusted sites, exploit software weaknesses, or trick users into entering information.',signs:'Unexpected redirects, misspelled addresses, browser security warnings, or urgent requests for codes.',protect:'Type the known address or open the official app. Keep your browser updated and do not bypass certificate warnings.',affected:'If you entered a password, open the real service separately, change it, end unfamiliar sessions, and contact the service if needed.',technical:'Defensive controls include TLS, secure session handling, input validation, access control, and timely patching.'}},
 {title:'Cloud Security',minutes:6,icon:'☁️',summary:'Protect online accounts and stored files with unique passwords and account recovery controls.',lesson:concepts[5]},
 {title:'Threat Intelligence',minutes:6,icon:'🔎',summary:'Learn how to judge a security report by its source, date, and confirmation status.',lesson:{title:'Threat intelligence',simple:'Threat intelligence is information that helps people understand possible cyber risks and decide what to do.',example:'A software maker publishes a dated advisory naming affected versions and the available update.',happens:'Researchers, response teams, and vendors collect and verify technical observations before sharing them.',signs:'Useful reports name a source, date, affected products, confidence, and practical steps.',protect:'Prefer official advisories. Check whether a claim is confirmed, reported, or still under investigation.',affected:'Follow the vendor or government advisory for your product. Avoid forwarding unverified claims as fact.',technical:'Threat intelligence is contextual, sourced information about threat actors, indicators, vulnerabilities, or tactics.'}},
 {title:'Incident Response',minutes:7,icon:'🧯',summary:'Use a calm, ordered plan after clicking a suspicious link or sharing account information.',lesson:{title:'Incident response',simple:'Incident response is a clear set of steps to limit harm and recover after something suspicious happens.',example:'If you typed a password into a fake page, secure the real account from its official app.',happens:'The right response depends on what happened and which account, device, or payment method is involved.',signs:'Unexpected sign-ins, password reset notices, unfamiliar transactions, or an app installed from an unknown source.',protect:'Pause, avoid further links, preserve useful alerts, and use a trusted device for account recovery.',affected:'Change exposed passwords, end unknown sessions, enable MFA, and contact your bank through its official channel if money may be involved.',technical:'Response commonly includes preparation, detection, containment, eradication, recovery, and post-incident review.'}},
];
const moduleQuizzes=[
 [{q:'What is cybersecurity mainly meant to protect?',o:['Devices, accounts, and information','Only a computer screen','The speed of the internet'],a:0,e:'Cybersecurity uses habits and safeguards to protect devices, accounts, networks, and information.'},{q:'Which password habit is safer?',o:['Reuse one easy password everywhere','Use a unique password for each important account','Share passwords with trusted callers'],a:1,e:'Unique passwords help stop a breach at one service from opening your other accounts.'},{q:'What should you do with an unexpected sign-in code?',o:['Share it with the caller','Post it for help online','Keep it private and check your account through its official app'],a:2,e:'One-time codes are secret. A request for one may be an attempt to access your account.'}],
 [{q:'A message says your bank account will close unless you sign in through its link. What is safest?',o:['Open your bank app directly or call the number on your card','Tap quickly before the deadline','Reply with your password'],a:0,e:'Urgency and unexpected login links are common phishing signs. Use a trusted route to reach the bank.'},{q:'What is phishing?',o:['A routine software update','A message or site that imitates someone trusted to trick you','A type of screen lock'],a:1,e:'Phishing uses impersonation to trick people into sharing information or doing something unsafe.'},{q:'A QR code is on an unexpected payment notice. What should you do?',o:['Scan and pay immediately','Share the code with friends','Verify the request using the organization’s official app or website'],a:2,e:'QR codes can hide their destination. Verify the request through a channel you trust.'}],
 [{q:'Why review app permissions?',o:['To check whether access matches what the app needs','To make every app an administrator','To disable all phone updates'],a:0,e:'Permissions control access to things such as photos, location, or microphone. Give only access that makes sense.'},{q:'What is a good way to get phone app updates?',o:['Use a random link in a text','Use the official app store and keep the OS updated','Install any file that promises a free upgrade'],a:1,e:'Official stores and operating-system updates reduce the chance of installing altered apps or missing fixes.'},{q:'A phone acts strangely after an unfamiliar app was installed. What is a reasonable first step?',o:['Assume it is definitely hacked','Give the app more permissions','Review the app and its permissions, and use trusted support if concerns continue'],a:2,e:'Odd behavior can have many causes. Review recent changes without jumping to a conclusion.'}],
 [{q:'What is a public Wi-Fi network?',o:['A shared connection other people may also use','A guarantee that all data is private','A replacement for a screen lock'],a:0,e:'Public Wi-Fi is shared. Use care with sensitive activity and heed browser security warnings.'},{q:'A Wi-Fi login page asks for unusual bank details. What should you do?',o:['Enter them to get connected','Do not enter them; verify the network with the venue','Turn off your phone’s screen lock'],a:1,e:'A hotspot login should not need your bank password or one-time code.'},{q:'What does HTTPS help provide?',o:['A secure, encrypted connection to the website you reached','Proof that every website is honest','Proof that a device has no malware'],a:0,e:'HTTPS encrypts the connection, but it does not by itself prove the site is trustworthy.'}],
 [{q:'What is a safer way to open a bank website?',o:['Tap a shortened link in an unexpected message','Use a saved official address or the bank’s official app','Search and click the first sponsored result'],a:1,e:'Use an address or app you already trust, especially for passwords and financial activity.'},{q:'What should you do if a browser shows a certificate warning?',o:['Stop and verify the site; do not bypass the warning','Ignore it and enter your password','Install a suggested unknown extension'],a:0,e:'A certificate warning can mean the connection identity cannot be verified.'},{q:'What is a fake website often trying to do?',o:['Improve your screen brightness','Imitate a real service to steal information or payments','Update the phone safely'],a:1,e:'Lookalike sites try to make people trust a false address or page.'}],
 [{q:'Which step best protects cloud accounts?',o:['Use a unique password and turn on MFA','Use the same password as your email','Share recovery codes with support callers'],a:0,e:'Unique credentials and multi-factor authentication make account takeover harder.'},{q:'Where should you check an account security alert?',o:['Through the official service app/site opened directly','Using the alert’s suspicious link','By replying with your password'],a:0,e:'Open the service yourself from a trusted route to see whether the alert is genuine.'},{q:'Why keep recovery information current?',o:['So you can regain access if locked out','So strangers can reset your account','To make cloud files public'],a:0,e:'Current recovery methods help you restore access if you lose a device or forget a password.'}],
 [{q:'Which source is strongest for a product vulnerability notice?',o:['An anonymous forwarded post','The affected vendor’s dated security advisory','A screenshot with no link'],a:1,e:'Vendor advisories provide product-specific affected versions and recommended actions.'},{q:'What should a useful threat report include?',o:['A source, date, affected products, and confidence','Only an alarming headline','A request to forward it to everyone'],a:0,e:'Source and date help readers verify and judge whether the information is relevant.'},{q:'What should you do with an unverified attack rumor?',o:['Label it confirmed','Avoid spreading it as fact and seek reliable confirmation','Add a made-up threat score'],a:1,e:'Threat intelligence should separate confirmed information from reports and uncertainty.'}],
 [{q:'You entered a password on a suspicious site. What should you do first?',o:['Change it using the real service from a trusted device','Wait for the site to contact you','Send the password to a friend'],a:0,e:'Use the official app/site from a trusted device, change the exposed password, and review sessions.'},{q:'If a suspicious message may involve your bank, what is safest?',o:['Call the number in that message','Contact the bank through its official app or the number on your card','Reply with your one-time code'],a:1,e:'Official contact channels reduce the chance of reaching the scammer.'},{q:'Why preserve relevant alerts or messages?',o:['They may help support or investigators understand what happened','They automatically undo the incident','They prove the sender is legitimate'],a:0,e:'Keeping relevant evidence can help the service provider or responder assess the situation.'}],
 [{q:'What is privilege escalation?',o:['Gaining higher access than a user or process should have','Changing your wallpaper','Installing an ordinary update'],a:0,e:'Privilege escalation is a security issue where access expands beyond what was intended.'},{q:'Does one alert prove that a device is compromised?',o:['Yes, always','No; investigators compare multiple reliable signals','Only if the phone is warm'],a:1,e:'A single signal may have harmless explanations. Strong conclusions need corroborating evidence.'},{q:'What is a sound defensive practice?',o:['Patch promptly, limit privileges, and keep tested backups','Disable all safeguards','Run unknown code to see what it does'],a:0,e:'Layered defensive controls reduce risk and help recovery.'}]
];
function progressKey(){return `cybershield.learning.v1.${activeUserId||'guest'}`}
function saveLearningState(){try{localStorage.setItem(progressKey(),JSON.stringify(learningState))}catch{showToast('Progress could not be saved in this browser.')};renderLearningProgress()}
function loadLearningState(){learningState={completed:[],level:'Beginner',quizResults:{}};try{const saved=JSON.parse(localStorage.getItem(progressKey())||'{}');if(Array.isArray(saved.completed))learningState.completed=[...new Set(saved.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<lessonModules.length))].sort((a,b)=>a-b);if(saved.quizResults&&typeof saved.quizResults==='object')learningState.quizResults=saved.quizResults;if(['Beginner','Intermediate','Advanced'].includes(saved.level))learningState.level=saved.level}catch{};const level=document.getElementById('level');if(level)level.value=learningState.level;renderLearningProgress()}
function nextLessonIndex(){for(let i=0;i<lessonModules.length;i++)if(!learningState.completed.includes(i))return i;return lessonModules.length-1}
function renderLearningProgress(){const count=learningState.completed.length,next=nextLessonIndex(),progress=document.getElementById('lesson-progress'),profile=document.getElementById('profile-progress'),list=document.getElementById('path-list'),title=document.getElementById('lesson-title'),summary=document.getElementById('lesson-summary'),kicker=document.getElementById('lesson-kicker'),art=document.getElementById('lesson-art'),button=document.getElementById('start-lesson'),foot=document.getElementById('lesson-foot');if(progress)progress.textContent=`${count} of ${lessonModules.length} modules completed`;if(profile)profile.textContent=`${count} of ${lessonModules.length} modules completed`;const homeTitle=document.getElementById('home-learning-title'),homeSubtitle=document.getElementById('home-learning-subtitle');if(homeTitle)homeTitle.textContent=count===lessonModules.length?'Learning path complete':`${count} of ${lessonModules.length} modules completed`;if(homeSubtitle)homeSubtitle.textContent=count===lessonModules.length?'All modules complete · Revisit any lesson':`Next · ${lessonModules[next].title}`;if(list){list.innerHTML=lessonModules.map((m,i)=>{const done=learningState.completed.includes(i),locked=false;const status=done?'COMPLETED':locked?'LOCKED':count?'CONTINUE':'START HERE';return `<button type="button" class="path-row ${done?'completed':''} ${i===next?'current':''} ${locked?'locked':''}" data-lesson="${i}" ${locked?'disabled':''} aria-label="${m.title}: ${status.toLowerCase()}"><span class="path-number">${done?'✓':locked?'🔒':i+1}</span><strong>${m.title}</strong><small>${status}</small></button>`}).join('');list.querySelectorAll('[data-lesson]:not(:disabled)').forEach(b=>b.addEventListener('click',()=>openLesson(Number(b.dataset.lesson))))}const module=lessonModules[next];if(title)title.textContent=count===lessonModules.length?'All modules complete':module.title;if(summary)summary.textContent=count===lessonModules.length?'You finished the learning path. Revisit any module to review its key ideas.':module.summary;if(kicker)kicker.textContent=count===lessonModules.length?'LEARNING PATH COMPLETE':`NEXT MODULE · ${module.minutes} MIN`;if(art)art.textContent=count===lessonModules.length?'✓':module.icon;if(button){button.disabled=false;button.innerHTML=count===lessonModules.length?'Review final module <span>→</span>':`${count?'Continue':'Start'} module ${next+1} <span>→</span>`;button.onclick=()=>openLesson(count===lessonModules.length?lessonModules.length-1:next)}if(foot)foot.innerHTML=count===lessonModules.length?'All 9 modules completed <span>·</span> Nice work':'Progress is saved in this browser <span>·</span> Sign-in required'}
function initLearningProgress(){loadLearningState();document.getElementById('level')?.addEventListener('change',e=>{learningState.level=e.target.value;saveLearningState()})}
function openLesson(index){const m=lessonModules[index];if(!m)return;const done=learningState.completed.includes(index);openModal(m.title,conceptHtml({...m.lesson,title:m.title}),`MODULE ${index+1} OF ${lessonModules.length} · ${m.minutes} MIN`);lessonModalIndex=index;document.getElementById('modal-done').textContent=done?'Take knowledge check →':'Complete lesson & take knowledge check →';if(done)activeModalAction=()=>startKnowledgeCheck(index)}
function completeLesson(index){startKnowledgeCheck(index)}
let activeQuizIndex=null,activeQuizQuestion=0,activeQuizAnswers=[];
function startKnowledgeCheck(index){if(!lessonModules[index])return;activeQuizIndex=index;activeQuizQuestion=0;activeQuizAnswers=[];renderKnowledgeQuestion()}
function renderKnowledgeQuestion(){const index=activeQuizIndex,quiz=moduleQuizzes[index]||[];if(!quiz.length)return showToast('There is no quiz for this module yet.');const question=quiz[activeQuizQuestion];openModal('Knowledge check',`<p><strong>${lessonModules[index].title}</strong><br>Question ${activeQuizQuestion+1} of ${quiz.length}. Choose one answer.</p><div class="knowledge-options">${question.o.map((option,i)=>`<button type="button" class="knowledge-option" data-quiz-option="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${escapeProfileText(option)}</button>`).join('')}</div>`,'CHECK YOUR KNOWLEDGE');document.getElementById('modal-done').textContent=activeQuizQuestion===quiz.length-1?'See my results →':'Next question →';document.querySelectorAll('[data-quiz-option]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-quiz-option]').forEach(option=>{option.classList.remove('selected');option.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true')}));const advanceQuiz=()=>{const chosen=document.querySelector('[data-quiz-option][aria-pressed="true"]');if(!chosen){showToast('Choose an answer to continue.');activeModalAction=advanceQuiz;return}activeQuizAnswers[activeQuizQuestion]=Number(chosen.dataset.quizOption);if(activeQuizQuestion<quiz.length-1){activeQuizQuestion++;renderKnowledgeQuestion()}else finishKnowledgeCheck()};activeModalAction=advanceQuiz}
function finishKnowledgeCheck(){const index=activeQuizIndex,quiz=moduleQuizzes[index]||[],score=quiz.reduce((sum,item,i)=>sum+(activeQuizAnswers[i]===item.a?1:0),0),percentage=Math.round(score/quiz.length*100);learningState.quizResults=learningState.quizResults||{};learningState.quizResults[index]={score,total:quiz.length,percentage,completedAt:new Date().toISOString()};if(!learningState.completed.includes(index))learningState.completed.push(index);learningState.completed.sort((a,b)=>a-b);saveLearningState();activeQuizIndex=null;showKnowledgeResult(index,score,quiz,activeQuizAnswers.slice())}
function showKnowledgeResult(index,score,quiz,answers){const percentage=Math.round(score/quiz.length*100),performance=percentage===100?'Excellent work!':percentage>=67?'Good understanding.':'Review the lesson and try again.';const review=quiz.map((item,i)=>`<article class="knowledge-review"><strong>${i+1}. ${escapeProfileText(item.q)}</strong><p class="${answers[i]===item.a?'quiz-correct':'quiz-incorrect'}">Your answer: ${escapeProfileText(item.o[answers[i]]||'No answer')} · ${answers[i]===item.a?'Correct':'Review'}</p>${answers[i]!==item.a?`<p><strong>Correct answer:</strong> ${escapeProfileText(item.o[item.a])}</p>`:''}<p>${escapeProfileText(item.e)}</p></article>`).join('');openModal('Knowledge check results',`<div class="knowledge-score"><strong>${score}/${quiz.length}</strong><span>${percentage}%</span><p>${performance}</p></div><div class="knowledge-review-list">${review}</div><button type="button" class="button button-outline" id="retake-knowledge-check">Retake this knowledge check</button>`,'YOUR PERFORMANCE');document.getElementById('modal-done').textContent=index<lessonModules.length-1?'Continue to next module →':'Finish learning path';document.getElementById('retake-knowledge-check').addEventListener('click',()=>startKnowledgeCheck(index));activeModalAction=()=>{const next=lessonModules.findIndex((_,i)=>!learningState.completed.includes(i));if(next<0){openModal('Learning path complete',`<p>You completed all ${lessonModules.length} modules and knowledge checks. You can revisit any lesson and retake its quiz from the learning path.</p>`,'NICE WORK');return}showToast(`${lessonModules[index].title} quiz: ${score}/${quiz.length} (${percentage}%).`);openLesson(next)}}
function escapeProfileText(value){const span=document.createElement('span');span.textContent=String(value||'');return span.innerHTML}
function openProfileSettings(){const email=document.getElementById('auth-user-email')?.textContent||'Signed-in account';const name=document.getElementById('profile-name')?.textContent||'Your profile';const count=learningState.completed.length;const next=lessonModules.findIndex((_,i)=>!learningState.completed.includes(i));const nextName=next<0?'Learning path complete':lessonModules[next].title;const percent=Math.round(count/lessonModules.length*100);openModal('Profile & settings',`<div class="profile-settings"><section class="profile-summary"><span class="profile-large-avatar">${escapeProfileText((name||'A').slice(0,1).toUpperCase())}</span><div><span class="settings-label">SIGNED-IN ACCOUNT</span><strong>${escapeProfileText(name)}</strong><p>${escapeProfileText(email)}</p></div></section><section class="settings-section"><div class="settings-section-heading"><div><span class="settings-label">YOUR LEARNING</span><strong>${count} of ${lessonModules.length} modules completed</strong></div><span class="settings-percent">${percent}%</span></div><div class="settings-progress"><span style="width:${percent}%"></span></div><p class="settings-note">Next module: ${escapeProfileText(nextName)}</p></section><section class="settings-section"><label class="settings-label" for="profile-level">EXPLANATION LEVEL</label><select id="profile-level" class="profile-setting-select"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select><p class="settings-note">Choose how technical CyberShield’s explanations should be.</p></section><section class="settings-section settings-actions"><div><strong>Learning progress</strong><p class="settings-note">Saved in this browser for this account. It does not sync across devices.</p></div><button class="button button-outline" type="button" id="reset-learning">Reset progress</button></section><button class="button button-danger full" type="button" id="profile-signout">Sign out</button></div>`,'YOUR ACCOUNT');document.getElementById('modal-done').textContent='Close';const level=document.getElementById('profile-level');level.value=learningState.level;level.addEventListener('change',()=>{learningState.level=level.value;const chatLevel=document.getElementById('level');if(chatLevel)chatLevel.value=level.value;saveLearningState();showToast('Explanation setting saved.')});document.getElementById('reset-learning').addEventListener('click',()=>{if(!window.confirm('Reset this account’s learning progress in this browser?'))return;learningState.completed=[];learningState.quizResults={};saveLearningState();openProfileSettings();showToast('Learning progress reset.')});document.getElementById('profile-signout').addEventListener('click',confirmSignOut)}
