let threatRecords=[],activeThreatCategory='All topics',threatVisibleCount=12;
function parseThreatCsv(source){const rows=[];let row=[],cell='',quoted=false;source=source.replace(/^\uFEFF/,'');for(let i=0;i<source.length;i++){const ch=source[i];if(quoted){if(ch==='"'&&source[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=false;else cell+=ch}else if(ch==='"'&&cell==='')quoted=true;else if(ch===','){row.push(cell);cell=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(value=>value.trim()))rows.push(row);if(rows.length<2)return[];const headers=rows.shift().map(value=>value.trim().toLowerCase().replace(/[^a-z0-9]/g,''));return rows.map(values=>Object.fromEntries(headers.map((key,index)=>[key,(values[index]||'').trim()])))}
function threatValue(record,key){return record[key]||''}
function formatThreatNumber(value){const number=Number(String(value).replace(/,/g,''));return Number.isFinite(number)?new Intl.NumberFormat().format(number):'Not provided'}
function filterThreatRecords(){const category=activeThreatCategory.toLowerCase();return threatRecords.filter(record=>{const country=threatValue(record,'country').toLowerCase(),type=threatValue(record,'attacktype').toLowerCase(),industry=threatValue(record,'targetindustry').toLowerCase(),source=threatValue(record,'attacksource').toLowerCase(),defense=threatValue(record,'defensemechanismused').toLowerCase();if(category==='all topics')return true;if(category==='india')return country==='india';if(category==='mobile')return /mobile|telecom|phone/.test(`${type} ${industry}`);if(category==='banking')return /bank|financ/.test(industry);if(category==='ransomware')return type.includes('ransomware');if(category==='ai')return /\bai\b|artificial intelligence/.test(`${type} ${source} ${defense}`);return true}).sort((a,b)=>(Number(b.year)||0)-(Number(a.year)||0))}
function renderThreatRecords(){const list=document.getElementById('threat-data'),summary=document.getElementById('threat-data-summary');if(!list||!summary)return;const records=filterThreatRecords(),years=threatRecords.map(record=>Number(record.year)).filter(Number.isFinite),minYear=years.length?Math.min(...years):'—',maxYear=years.length?Math.max(...years):'—';summary.textContent=`${records.length.toLocaleString()} matching sample records · dataset years ${minYear}–${maxYear} · simulated, not verified reports`;if(!records.length){list.innerHTML='<div class="dataset-empty panel">No matching rows in this dataset. Try another topic.</div>';return}const cards=records.slice(0,threatVisibleCount).map(record=>{const country=threatValue(record,'country')||'Unknown country',year=threatValue(record,'year')||'Year not provided',type=threatValue(record,'attacktype')||'Threat type not specified',industry=threatValue(record,'targetindustry')||'Industry not specified',loss=threatValue(record,'financiallossinmillion'),affected=threatValue(record,'numberofaffectedusers'),vector=threatValue(record,'securityvulnerabilitytype'),defense=threatValue(record,'defensemechanismused'),resolution=threatValue(record,'incidentresolutiontimeinhours');const money=loss!==''&&Number.isFinite(Number(loss))?`$${Number(loss).toLocaleString(undefined,{maximumFractionDigits:2})}M`:'Not provided';return `<article class="threat-data-card panel"><div class="brief-meta"><span class="pill pill-yellow">SIMULATED SAMPLE</span><span>${escapeProfileText(year)} · ${escapeProfileText(country)}</span></div><h3>${escapeProfileText(type)} · ${escapeProfileText(industry)}</h3><p class="dataset-disclaimer">Illustrative dataset record; not a verified news report.</p><div class="dataset-facts"><div><small>ESTIMATED LOSS</small><b>${money}</b></div><div><small>AFFECTED USERS</small><b>${affected?escapeProfileText(formatThreatNumber(affected)):'Not provided'}</b></div><div><small>VULNERABILITY</small><b>${escapeProfileText(vector||'Not provided')}</b></div><div><small>DEFENSE</small><b>${escapeProfileText(defense||'Not provided')}</b></div></div>${resolution?`<small class="dataset-resolution">Reported resolution time in sample: ${escapeProfileText(resolution)} hours</small>`:''}</article>`}).join('');const more=records.length>threatVisibleCount?'<button type="button" class="button button-outline dataset-more" id="threat-load-more">Show more records</button>':'';list.innerHTML=cards+more;document.getElementById('threat-load-more')?.addEventListener('click',()=>{threatVisibleCount+=12;renderThreatRecords()})}
async function loadThreatDataset(){const summary=document.getElementById('threat-data-summary');try{const response=await fetch('./data/cyber-threats.csv');if(!response.ok)throw new Error('CSV file not found');threatRecords=parseThreatCsv(await response.text());if(!threatRecords.length)throw new Error('No data rows were found');renderThreatRecords()}catch(error){summary.textContent='Could not load the dataset. Confirm that site/data/cyber-threats.csv exists, then reload the page.';document.getElementById('threat-data').innerHTML='<div class="dataset-empty panel">The CSV is not connected yet. Check the filename and location.</div>'}}
