const form=document.getElementById('chat-form'),input=document.getElementById('chat-input'),messages=document.getElementById('chat-messages');function addMessage(text,role){const wrap=document.createElement('div');wrap.className=`message ${role==='user'?'user-message':'assistant-message'}`;const bubble=document.createElement('div');bubble.className='bubble';const p=document.createElement('p');p.textContent=text;bubble.appendChild(p);const sm=document.createElement('small');sm.textContent='Just now';bubble.appendChild(sm);if(role!=='user'){const icon=document.createElement('span');icon.className='message-avatar';icon.textContent='✳';wrap.appendChild(icon)}wrap.appendChild(bubble);messages.appendChild(wrap);wrap.scrollIntoView({behavior:'smooth',block:'nearest'})}
let cyberShieldChatHistory=[];
let cyberShieldChatBusy=false;
function appendAssistantReply(text,{error=false,sources=[]}={}){
  const wrap=document.createElement('div');wrap.className='message assistant-message';
  const icon=document.createElement('span');icon.className='message-avatar';icon.textContent='✳';
  const bubble=document.createElement('div');bubble.className='bubble';
  const content=document.createElement('p');content.textContent=text;content.style.whiteSpace='pre-wrap';content.style.lineHeight='1.65';
  if(error)content.style.color='#8b3027';
  bubble.appendChild(content);
  if(!error&&Array.isArray(sources)&&sources.length){
    const sourceTitle=document.createElement('strong');sourceTitle.textContent='Sources';sourceTitle.style.display='block';sourceTitle.style.marginTop='10px';sourceTitle.style.fontSize='10px';bubble.appendChild(sourceTitle);
    const sourceList=document.createElement('ul');sourceList.style.margin='5px 0 0';sourceList.style.paddingLeft='18px';
    sources.slice(0,8).forEach(source=>{try{const url=new URL(source.url);if(!['https:','http:'].includes(url.protocol))return;const item=document.createElement('li');const link=document.createElement('a');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=source.title||url.hostname;link.style.color='inherit';item.appendChild(link);sourceList.appendChild(item)}catch{}});
    if(sourceList.childElementCount)bubble.appendChild(sourceList);
  }
  const sm=document.createElement('small');sm.textContent=error?'Connection issue':'AI assistant · Educational guidance';bubble.appendChild(sm);
  wrap.append(icon,bubble);messages.appendChild(wrap);wrap.scrollIntoView({behavior:'smooth',block:'nearest'});
}
async function sendQuestion(text){
  const question=text.trim();if(!question||cyberShieldChatBusy)return;
  addMessage(question,'user');
  cyberShieldChatHistory.push({role:'user',content:question});
  cyberShieldChatHistory=cyberShieldChatHistory.slice(-12);
  cyberShieldChatBusy=true;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;input.disabled=true;
  try{
    if(!cyberShieldAuthClient)throw new Error('Sign-in is not configured. Please sign in again after Supabase setup.');
    const {data,error:sessionError}=await cyberShieldAuthClient.auth.getSession();
    if(sessionError)throw sessionError;
    const token=data.session?.access_token;if(!token)throw new Error('Your sign-in session expired. Sign in again to continue.');
    const response=await fetch('/.netlify/functions/cybershield-chat',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify({messages:cyberShieldChatHistory,level:document.getElementById('level').value})});
    const result=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(result.error||`The assistant could not respond (HTTP ${response.status}).`);
    if(typeof result.answer!=='string'||!result.answer.trim())throw new Error('The assistant returned an empty response. Please try again.');
    const citedAnswer=result.sources?.length?`${result.answer}\n\nSources: ${result.sources.map(source=>`${source.title||source.url} (${source.url})`).join('; ')}`:result.answer;
    cyberShieldChatHistory.push({role:'assistant',content:citedAnswer});cyberShieldChatHistory=cyberShieldChatHistory.slice(-12);
    appendAssistantReply(result.answer,{sources:result.sources});
  }catch(error){appendAssistantReply(error.message||'The assistant is temporarily unavailable. Please try again.',{error:true});}
  finally{cyberShieldChatBusy=false;submit.disabled=false;input.disabled=false;input.focus();}
}
form.addEventListener('submit',e=>{e.preventDefault();sendQuestion(input.value);input.value=''});document.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>sendQuestion(b.textContent));document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{navigate('assistant');sendQuestion(b.dataset.prompt)});
