// SMS spam model: load only when requested; the pasted message stays in this page.
let cyberShieldSmsModelPromise;
function loadCyberShieldSmsModel(){
  if(!cyberShieldSmsModelPromise){
    cyberShieldSmsModelPromise=fetch('./sms-model.json')
      .then(response=>{if(!response.ok)throw new Error(`Model request failed (${response.status})`);return response.json()})
      .then(model=>{
        if(!model.vocabulary||!model.featureLogProb?.ham||!model.featureLogProb?.spam||!model.classLogPrior?.ham||!model.classLogPrior?.spam)throw new Error('The model file is not in the expected format. Retrain it with backend/train_model.py.');
        return model;
      });
  }
  return cyberShieldSmsModelPromise;
}
function cyberShieldSpamScore(text,model){
  const words=text.toLocaleLowerCase().match(/[\p{L}\p{N}_]+/gu)||[];
  const terms=[...words,...words.slice(0,-1).map((word,index)=>`${word} ${words[index+1]}`)];
  let ham=model.classLogPrior.ham,spam=model.classLogPrior.spam;
  for(const term of terms){
    const index=model.vocabulary[term];
    if(index!==undefined){ham+=model.featureLogProb.ham[index];spam+=model.featureLogProb.spam[index]}
  }
  const max=Math.max(ham,spam),hamWeight=Math.exp(ham-max),spamWeight=Math.exp(spam-max);
  return spamWeight/(spamWeight+hamWeight);
}
const smsCheckButton=document.getElementById('check-sms');
if(smsCheckButton){
  smsCheckButton.addEventListener('click',async()=>{
    const message=document.getElementById('sms-message').value.trim();
    const result=document.getElementById('sms-result');
    const status=document.getElementById('sms-model-status');
    if(!message){result.hidden=false;result.className='sms-result uncertain';result.textContent='Paste a message first, then choose Check message.';return}
    smsCheckButton.disabled=true;result.hidden=false;result.className='sms-result';result.textContent='Loading the model and checking this message…';status.textContent='Loading the local model…';
    try{
      const model=await loadCyberShieldSmsModel();
      const score=cyberShieldSpamScore(message,model);
      const percent=Math.round(score*100);
      if(score>=0.75){result.className='sms-result suspicious';result.textContent=`Potentially spam-like (model score: ${percent}/100). Don't open unexpected links or share passwords or verification codes. Check with the organization through its official app or phone number.`}
      else if(score<=0.25){result.className='sms-result low-risk';result.textContent=`No common spam pattern was detected (model score: ${percent}/100). This does not prove the message is safe; verify unexpected requests independently.`}
      else{result.className='sms-result uncertain';result.textContent=`The result is uncertain (model score: ${percent}/100). Avoid links or payment requests until you verify the sender through an official channel.`}
      status.textContent='Checked locally in this browser. Your message was not uploaded.';
    }catch(error){
      result.className='sms-result error';result.textContent='Could not load sms-model.json. Make sure the file is next to index.html and open the app through Netlify or a local web server, not by double-clicking the HTML file.';
      status.textContent=error.message;
    }finally{smsCheckButton.disabled=false}
  });
}

// Hosted email/password identity. Password verification is performed by Supabase Auth.
const authScreen=document.getElementById('auth-screen');
const appShell=document.getElementById('app-shell');
const authForm=document.getElementById('auth-form');
const authFeedback=document.getElementById('auth-feedback');
const authSubmit=document.getElementById('auth-submit');
const authPassword=document.getElementById('auth-password');
const authConfirm=document.getElementById('auth-confirm');
const authConfirmWrap=document.getElementById('auth-confirm-wrap');
const authIntro=document.getElementById('auth-intro');
let cyberShieldAuthMode='signin';
let cyberShieldAuthClient=null;
function setAuthMessage(message,kind=''){authFeedback.textContent=message;authFeedback.className=`auth-feedback ${kind}`}
function setAuthMode(mode){
  cyberShieldAuthMode=mode;
  const signup=mode==='signup';
  document.getElementById('auth-title').textContent=signup?'Create your account.':'Welcome back.';
  authIntro.textContent=signup?'Create an account with your email address and a strong password.':'Sign in with your email and password to continue.';
  authSubmit.innerHTML=signup?'Create account <span>→</span>':'Sign in <span>→</span>';
  authPassword.autocomplete=signup?'new-password':'current-password';
  authPassword.minLength=signup?10:0;
  authConfirmWrap.hidden=!signup;
  authConfirm.required=signup;
  document.getElementById('auth-signin-tab').classList.toggle('selected',!signup);
  document.getElementById('auth-signup-tab').classList.toggle('selected',signup);
  document.getElementById('auth-signin-tab').setAttribute('aria-selected',String(!signup));
  document.getElementById('auth-signup-tab').setAttribute('aria-selected',String(signup));
  setAuthMessage(signup?'Use at least 10 characters for a new password.':'Sign in with your registered email and password.');
}
function showCyberShieldAuth(){activeUserId=null;authScreen.hidden=false;appShell.hidden=true}
function showCyberShieldApp(session){
  if(!session){showCyberShieldAuth();return}
  authScreen.hidden=true;appShell.hidden=false;
  const user=session.user||{};const nextId=user.id||'guest';if(activeUserId!==nextId){activeUserId=nextId;loadLearningState()}
  const email=document.getElementById('auth-user-email');if(email)email.textContent=user.email||'Signed-in account';
  const name=user.user_metadata?.full_name||user.user_metadata?.name||(user.email?user.email.split('@')[0]:'Your profile');
  const profileName=document.getElementById('profile-name');if(profileName)profileName.textContent=name;
  const avatar=document.getElementById('profile-avatar');if(avatar)avatar.textContent=String(name).trim().charAt(0).toUpperCase()||'A';
  const topAvatar=document.getElementById('profile-open-top');if(topAvatar)topAvatar.textContent=String(name).trim().charAt(0).toUpperCase()||'A';
}
document.getElementById('auth-signin-tab').addEventListener('click',()=>setAuthMode('signin'));
document.getElementById('auth-signup-tab').addEventListener('click',()=>setAuthMode('signup'));
const authConfig=window.CYBERSHIELD_SUPABASE_CONFIG||{};
if(!authConfig.url||!authConfig.anonKey){
  setAuthMessage('Setup needed: add your Supabase Project URL and public anon/publishable key to auth-config.js. No password will be collected until it is configured.','setup');
}else if(!window.supabase||typeof window.supabase.createClient!=='function'){
  setAuthMessage('The Supabase sign-in library did not load. Check your internet connection and reload this page.','error');
}else{
  try{
    cyberShieldAuthClient=window.supabase.createClient(authConfig.url,authConfig.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    cyberShieldAuthClient.auth.onAuthStateChange((_event,session)=>showCyberShieldApp(session));
    cyberShieldAuthClient.auth.getSession().then(({data,error})=>{
      if(error)throw error;
      if(data.session)showCyberShieldApp(data.session);else showCyberShieldAuth();
    }).catch(error=>{showCyberShieldAuth();setAuthMessage(error.message||'Could not check your sign-in session.','error')});
  }catch(error){setAuthMessage('Could not initialize sign-in. Check the Supabase settings in auth-config.js.','error')}
}
authForm.addEventListener('submit',async event=>{
  event.preventDefault();
  const email=document.getElementById('auth-email').value.trim();
  const password=authPassword.value;
  if(!cyberShieldAuthClient){setAuthMessage('Sign-in is not connected yet. Complete the Supabase setup described below.','setup');return}
  if(cyberShieldAuthMode==='signup'&&password!==authConfirm.value){setAuthMessage('The passwords do not match. Please re-enter them.','error');return}
  if(cyberShieldAuthMode==='signup'&&password.length<10){setAuthMessage('Choose a password with at least 10 characters.','error');return}
  authSubmit.disabled=true;setAuthMessage(cyberShieldAuthMode==='signup'?'Creating your account…':'Signing you in…');
  try{
    if(cyberShieldAuthMode==='signup'){
      const {data,error}=await cyberShieldAuthClient.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin}});
      if(error)throw error;
      authPassword.value='';authConfirm.value='';
      if(data.session)showCyberShieldApp(data.session);
      else setAuthMessage('Account created. Check your email for the confirmation link, then come back here to sign in.','success');
    }else{
      const {data,error}=await cyberShieldAuthClient.auth.signInWithPassword({email,password});
      if(error)throw error;
      authPassword.value='';showCyberShieldApp(data.session);
    }
  }catch(error){setAuthMessage(error.message||'Sign-in failed. Check your details and try again.','error')}
  finally{authSubmit.disabled=false}
});
